//
// It is the paired counterpart to R_Calloc / R_chk_calloc, releasing
// heap memory allocated by CALLOC (= R_chk_calloc) and nulling the
// pointer variable via the C comma operator.
//
// In rpart, the macro is used at six call sites across three files:
//
//   free_tree.c:13  — R_Free(spl)   frees a pSplit (Split *) node
//   free_tree.c:29  — R_Free(node)  frees a pNode  (Node  *) node
