// All six call sites free CALLOC-allocated heap blocks.  They are
// NOT arena-managed and must NOT be touched by ArenaFrame destruction.
//
// This header also provides the full set of helpers from R_ext/RS.h:
//   R_chk_calloc, R_chk_realloc, R_chk_free, R_chk_memcpy, R_chk_memset,
//   R_Calloc, R_Realloc, Memcpy, Memzero, CallocCharBuf.
